public with sharing class RecordSearchService {
    public class SearchException extends Exception {}

    /**
     * Generic record finder. Returns up to maxRows records matching the equality filters.
     * All object/field names are resolved case-insensitively and the query is built
     * without string concatenation of user values, so it is safe from SOQL injection.
     */
    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // ---- validate maxRows -------------------------------------------------
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }

        // ---- validate fields list ---------------------------------------------
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('fields is required and must not be empty.');
        }

        // ---- resolve object (case-insensitive) --------------------------------
        Schema.SObjectType sot = getSObjectType(objectApiName);
        if (sot == null) {
            throw new SearchException('Object does not exist: ' + String.valueOf(objectApiName));
        }

        DescribeSObjectResult objDesc = sot.getDescribe();
        if (!objDesc.isAccessible()) {
            throw new SearchException('Running user cannot read object: ' + objectApiName);
        }

        String objectName = objDesc.getName();
        Map<String, Schema.SObjectField> fieldMap = objDesc.fields.getMap();

        // ---- build select list (Id is always included) ------------------------
        Set<String> selectedSet = new Set<String>{'Id'};
        List<String> selectedFields = new List<String>{'Id'};

        for (String field : fields) {
            String fieldName = getFieldName(fieldMap, field);
            if (fieldName == null) {
                throw new SearchException('Field does not exist on object: ' + String.valueOf(field));
            }

            DescribeFieldResult dfr = fieldMap.get(fieldName).getDescribe();
            if (!dfr.isAccessible()) {
                throw new SearchException('Running user cannot read field: ' + field);
            }

            if (selectedSet.add(fieldName)) {
                selectedFields.add(fieldName);
            }
        }

        // ---- validate filters -------------------------------------------------
        List<String> filterFieldNames = new List<String>();
        List<Object> filterValues = new List<Object>();

        if (filters != null && !filters.isEmpty()) {
            for (String key : filters.keySet()) {
                String fieldName = getFieldName(fieldMap, key);
                if (fieldName == null) {
                    throw new SearchException('Filter field does not exist on object: ' + key);
                }

                DescribeFieldResult dfr = fieldMap.get(fieldName).getDescribe();
                if (!dfr.isAccessible()) {
                    throw new SearchException('Running user cannot read filter field: ' + key);
                }
                if (!dfr.isFilterable()) {
                    throw new SearchException('Filter field cannot be filtered: ' + key);
                }

                filterFieldNames.add(fieldName);
                filterValues.add(filters.get(key));
            }
        }

        // ---- validate order by ------------------------------------------------
        String orderByFieldName = null;
        if (String.isNotBlank(orderByField)) {
            orderByFieldName = getFieldName(fieldMap, orderByField);
            if (orderByFieldName == null) {
                throw new SearchException('Order by field does not exist on object: ' + orderByField);
            }

            DescribeFieldResult dfr = fieldMap.get(orderByFieldName).getDescribe();
            if (!dfr.isAccessible()) {
                throw new SearchException('Running user cannot read order by field: ' + orderByField);
            }
            if (!dfr.isSortable()) {
                throw new SearchException('Order by field cannot be sorted: ' + orderByField);
            }
        }

        // ---- build and run the single SOQL query ------------------------------
        String query = buildQuery(
            objectName,
            selectedFields,
            filterFieldNames,
            filterValues,
            orderByFieldName,
            maxRows
        );

        try {
            return Database.query(query);
        } catch (Exception e) {
            throw new SearchException('Query execution failed: ' + e.getMessage());
        }
    }

    // -------------------------------------------------------------------------
    // Private helpers
    // -------------------------------------------------------------------------

    private static Schema.SObjectType getSObjectType(String objectApiName) {
        if (String.isBlank(objectApiName)) {
            return null;
        }

        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        Schema.SObjectType sot = globalDescribe.get(objectApiName);
        if (sot != null) {
            return sot;
        }

        // Case-insensitive fallback
        for (String key : globalDescribe.keySet()) {
            if (key.equalsIgnoreCase(objectApiName)) {
                return globalDescribe.get(key);
            }
        }
        return null;
    }

    private static String getFieldName(Map<String, Schema.SObjectField> fieldMap, String fieldApiName) {
        if (String.isBlank(fieldApiName)) {
            return null;
        }

        if (fieldMap.containsKey(fieldApiName)) {
            return fieldApiName;
        }

        // Case-insensitive fallback
        for (String key : fieldMap.keySet()) {
            if (key.equalsIgnoreCase(fieldApiName)) {
                return key;
            }
        }
        return null;
    }

    private static String buildQuery(
        String objectApiName,
        List<String> fields,
        List<String> filterFields,
        List<Object> filterValues,
        String orderByField,
        Integer maxRows
    ) {
        String q = 'SELECT ';
        for (Integer i = 0; i < fields.size(); i++) {
            if (i > 0) {
                q += ', ';
            }
            q += fields.get(i);
        }

        q += ' FROM ' + objectApiName;

        if (!filterFields.isEmpty()) {
            q += ' WHERE ';
            for (Integer i = 0; i < filterFields.size(); i++) {
                if (i > 0) {
                    q += ' AND ';
                }
                q += filterFields.get(i);
                q += ' = ';
                q += formatValue(filterValues.get(i));
            }
        }

        if (String.isNotBlank(orderByField)) {
            q += ' ORDER BY ' + orderByField + ' ASC';
        }

        q += ' LIMIT ' + maxRows;
        return q;
    }

    private static String formatValue(Object value) {
        if (value == null) {
            return 'null';
        }

        if (value instanceof Boolean) {
            return (Boolean) value ? 'true' : 'false';
        }

        if (value instanceof Integer || value instanceof Long || value instanceof Decimal || value instanceof Double) {
            return String.valueOf(value);
        }

        if (value instanceof Date) {
            Date d = (Date) value;
            return '\'' + d.year() + '-' + pad2(d.month()) + '-' + pad2(d.day()) + '\'';
        }

        // String, Id, or any other type: escape single quotes and quote as a string literal
        return '\'' + String.escapeSingleQuotes(String.valueOf(value)) + '\'';
    }

    private static String pad2(Integer n) {
        String s = String.valueOf(n);
        return s.length() == 1 ? '0' + s : s;
    }
}
