@isTest
private class AddressVerificationServiceTest {

    private static final String API_ENDPOINT = 'callout:FB_Address_API/v2/verify';

    /**
     * Captures the outbound request and returns a configurable response so each test can
     * assert the exact request contract and drive the service through every response path.
     */
    private class VerifyMock implements HttpCalloutMock {
        public HttpRequest capturedRequest;
        public Integer callCount = 0;
        public Integer statusCode = 200;
        public String responseBody;

        public HttpResponse respond(HttpRequest req) {
            callCount++;
            capturedRequest = req;
            HttpResponse res = new HttpResponse();
            res.setStatusCode(statusCode);
            res.setBody(responseBody == null ? defaultResponseBody() : responseBody);
            return res;
        }

        private String defaultResponseBody() {
            return '{"status":"VERIFIED","address":{"street":"456 Oak Ave","city":"Gotham","postalCode":"20002","country":"UK"}}';
        }
    }

    @isTest
    static void blankBillingStreetIsSkippedWithoutCallout() {
        VerifyMock mock = new VerifyMock();
        Test.setMock(HttpCalloutMock.class, mock);

        Account acct = new Account(Name = 'Acme', BillingCity = 'Metropolis');

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertEquals('SKIPPED', result.status);
        System.assertEquals(false, result.changed);
        System.assertEquals(0, mock.callCount);
        System.assertEquals(null, mock.capturedRequest);
    }

    @isTest
    static void verifiedResponseReturnsStatusAndLeavesAccountUntouched() {
        String street = '123 Main St';
        String city = 'Metropolis';
        String postal = '10001';
        String country = 'US';

        VerifyMock mock = new VerifyMock();
        mock.responseBody =
            '{"status":"VERIFIED","address":{"street":"456 Oak Ave","city":"Gotham","postalCode":"20002","country":"UK"}}';
        Test.setMock(HttpCalloutMock.class, mock);

        Account acct = new Account(Name = 'Acme', BillingStreet = street, BillingCity = city,
            BillingPostalCode = postal, BillingCountry = country);

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertEquals(1, mock.callCount);
        System.assertEquals('VERIFIED', result.status);
        System.assertEquals(false, result.changed);
        System.assertEquals(street, acct.BillingStreet);
        System.assertEquals(city, acct.BillingCity);
        System.assertEquals(postal, acct.BillingPostalCode);
        System.assertEquals(country, acct.BillingCountry);
        assertRequestContract(mock, street, city, postal, country);
    }

    @isTest
    static void correctedResponseOverwritesBillingFieldsAndMarksChanged() {
        String street = '123 Main St';
        String city = 'Metropolis';
        String postal = '10001';
        String country = 'US';

        VerifyMock mock = new VerifyMock();
        mock.responseBody =
            '{"status":"CORRECTED","address":{"street":"456 Oak Ave","city":"Gotham","postalCode":"20002","country":"UK"}}';
        Test.setMock(HttpCalloutMock.class, mock);

        Account acct = new Account(Name = 'Acme', BillingStreet = street, BillingCity = city,
            BillingPostalCode = postal, BillingCountry = country);

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertEquals(1, mock.callCount);
        System.assertEquals('CORRECTED', result.status);
        System.assertEquals(true, result.changed);
        System.assertEquals('456 Oak Ave', acct.BillingStreet);
        System.assertEquals('Gotham', acct.BillingCity);
        System.assertEquals('20002', acct.BillingPostalCode);
        System.assertEquals('UK', acct.BillingCountry);
        assertRequestContract(mock, street, city, postal, country);
    }

    @isTest
    static void invalidResponseReturnsStatusAndLeavesAccountUntouched() {
        String street = '123 Main St';
        String city = 'Metropolis';
        String postal = '10001';
        String country = 'US';

        VerifyMock mock = new VerifyMock();
        mock.responseBody =
            '{"status":"INVALID","address":{"street":"456 Oak Ave","city":"Gotham","postalCode":"20002","country":"UK"}}';
        Test.setMock(HttpCalloutMock.class, mock);

        Account acct = new Account(Name = 'Acme', BillingStreet = street, BillingCity = city,
            BillingPostalCode = postal, BillingCountry = country);

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertEquals(1, mock.callCount);
        System.assertEquals('INVALID', result.status);
        System.assertEquals(false, result.changed);
        System.assertEquals(street, acct.BillingStreet);
        System.assertEquals(city, acct.BillingCity);
        System.assertEquals(postal, acct.BillingPostalCode);
        System.assertEquals(country, acct.BillingCountry);
        assertRequestContract(mock, street, city, postal, country);
    }

    @isTest
    static void nonSuccessfulResponseThrowsAddressVerificationExceptionContainingStatusCode() {
        VerifyMock mock = new VerifyMock();
        mock.statusCode = 500;
        mock.responseBody = '{"error":"internal server error"}';
        Test.setMock(HttpCalloutMock.class, mock);

        Account acct = new Account(Name = 'Acme', BillingStreet = '123 Main St');

        Test.startTest();
        try {
            AddressVerificationService.verify(acct);
            System.assert(false, 'AddressVerificationException was not thrown for HTTP 500');
        } catch (AddressVerificationService.AddressVerificationException e) {
            System.assertNotEquals(null, e.getMessage());
            System.assert(e.getMessage().contains('500'),
                'Exception message should contain the status code, was: ' + e.getMessage());
        }
        Test.stopTest();
    }

    private static void assertRequestContract(VerifyMock mock, String street, String city, String postal,
        String country) {
        System.assertEquals(1, mock.callCount);
        HttpRequest req = mock.capturedRequest;
        System.assertNotEquals(null, req);
        System.assertEquals('POST', req.getMethod());
        System.assertEquals(API_ENDPOINT, req.getEndpoint());
        System.assertEquals('application/json', req.getHeader('Content-Type'));

        Map<String, Object> body = (Map<String, Object>) JSON.deserializeUntyped(req.getBody());
        System.assertNotEquals(null, body);
        System.assertEquals(street, body.get('street'));
        System.assertEquals(city, body.get('city'));
        System.assertEquals(postal, body.get('postalCode'));
        System.assertEquals(country, body.get('country'));
    }
}
