@IsTest
public class OpportunityWonHandlerTest {

    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final String STAGE_PROSPECTING = 'Prospecting';
    private static final String STAGE_QUALIFICATION = 'Qualification';
    private static final String NEXT_STEP_HANDOVER = 'Handover to Customer Success';
    private static final String TASK_SUBJECT = 'Customer kick-off';
    private static final String TASK_PRIORITY = 'High';

    @TestSetup
    static void testSetup() {
        insert new Account(Name = 'Warm Account', Rating = 'Warm');
        insert new Account(Name = 'Hot Account', Rating = 'Hot');
    }

    private static Id warmAccountId() {
        return [SELECT Id FROM Account WHERE Rating = 'Warm' LIMIT 1].Id;
    }

    private static Id hotAccountId() {
        return [SELECT Id FROM Account WHERE Rating = 'Hot' LIMIT 1].Id;
    }

    private static Opportunity newOpportunity(Id accountId, String stageName, Date closeDate) {
        return new Opportunity(
            Name = 'Test Opportunity',
            StageName = stageName,
            CloseDate = closeDate,
            AccountId = accountId,
            OwnerId = UserInfo.getUserId()
        );
    }

    @IsTest
    static void testInsertWonOpportunitySetsNextStepTaskAndAccountRating() {
        Id accountId = warmAccountId();
        Date closeDate = Date.today().addDays(30);
        Opportunity opp = newOpportunity(accountId, STAGE_CLOSED_WON, closeDate);

        Test.startTest();
        insert opp;
        Test.stopTest();

        Opportunity persisted = [SELECT NextStep FROM Opportunity WHERE Id = :opp.Id];
        System.assertEquals(NEXT_STEP_HANDOVER, persisted.NextStep,
            'NextStep must be set on a newly won insert');

        List<Task> tasks = [SELECT Subject, WhatId, OwnerId, ActivityDate, Priority
                            FROM Task WHERE WhatId = :opp.Id];
        System.assertEquals(1, tasks.size(), 'Exactly one task must be created');
        Task task = tasks[0];
        System.assertEquals(TASK_SUBJECT, task.Subject);
        System.assertEquals(opp.Id, task.WhatId);
        System.assertEquals(opp.OwnerId, task.OwnerId);
        System.assertEquals(closeDate.addDays(7), task.ActivityDate);
        System.assertEquals(TASK_PRIORITY, task.Priority);

        Account updatedAccount = [SELECT Rating FROM Account WHERE Id = :accountId];
        System.assertEquals('Hot', updatedAccount.Rating,
            'Account rating must become Hot');
    }

    @IsTest
    static void testInsertNonWonOpportunityChangesNothing() {
        Id accountId = warmAccountId();
        Date closeDate = Date.today().addDays(30);
        Opportunity opp = newOpportunity(accountId, STAGE_PROSPECTING, closeDate);

        Test.startTest();
        insert opp;
        Test.stopTest();

        Opportunity persisted = [SELECT NextStep FROM Opportunity WHERE Id = :opp.Id];
        System.assertEquals(null, persisted.NextStep,
            'NextStep must not be set for a non-won insert');

        System.assertEquals(0, [SELECT COUNT() FROM Task WHERE WhatId = :opp.Id],
            'No task must be created for a non-won insert');

        Account updatedAccount = [SELECT Rating FROM Account WHERE Id = :accountId];
        System.assertEquals('Warm', updatedAccount.Rating,
            'Account must not become Hot for a non-won insert');
    }

    @IsTest
    static void testUpdateFromNonWonToWon() {
        Id accountId = warmAccountId();
        Date closeDate = Date.today().addDays(30);
        Opportunity opp = newOpportunity(accountId, STAGE_PROSPECTING, closeDate);
        insert opp;

        opp.StageName = STAGE_CLOSED_WON;
        Test.startTest();
        update opp;
        Test.stopTest();

        Opportunity persisted = [SELECT NextStep FROM Opportunity WHERE Id = :opp.Id];
        System.assertEquals(NEXT_STEP_HANDOVER, persisted.NextStep,
            'NextStep must be set when an opportunity is newly won on update');

        List<Task> tasks = [SELECT Subject, ActivityDate, Priority
                            FROM Task WHERE WhatId = :opp.Id];
        System.assertEquals(1, tasks.size(), 'Exactly one task must be created on win');
        System.assertEquals(TASK_SUBJECT, tasks[0].Subject);
        System.assertEquals(closeDate.addDays(7), tasks[0].ActivityDate);
        System.assertEquals(TASK_PRIORITY, tasks[0].Priority);

        Account updatedAccount = [SELECT Rating FROM Account WHERE Id = :accountId];
        System.assertEquals('Hot', updatedAccount.Rating,
            'Account rating must become Hot on win');
    }

    @IsTest
    static void testUpdateAlreadyWonOpportunityDoesNotResetNextStepOrCreateTask() {
        Id accountId = warmAccountId();
        Date closeDate = Date.today().addDays(30);
        Opportunity opp = newOpportunity(accountId, STAGE_CLOSED_WON, closeDate);
        insert opp;

        System.assertEquals(1, [SELECT COUNT() FROM Task WHERE WhatId = :opp.Id]);

        opp.NextStep = 'Some other next step';
        opp.Description = 'Non-stage field update';
        Test.startTest();
        update opp;
        Test.stopTest();

        Opportunity persisted = [SELECT NextStep FROM Opportunity WHERE Id = :opp.Id];
        System.assertEquals('Some other next step', persisted.NextStep,
            'Already-won updates must not reset NextStep');

        Integer tasksAfter = [SELECT COUNT() FROM Task WHERE WhatId = :opp.Id];
        System.assertEquals(1, tasksAfter,
            'Already-won updates must not create new tasks');
    }

    @IsTest
    static void testUpdateFromWonToNonWonCreatesNoNewTask() {
        Id accountId = warmAccountId();
        Date closeDate = Date.today().addDays(30);
        Opportunity opp = newOpportunity(accountId, STAGE_CLOSED_WON, closeDate);
        insert opp;

        System.assertEquals(1, [SELECT COUNT() FROM Task WHERE WhatId = :opp.Id]);

        opp.StageName = STAGE_PROSPECTING;
        Test.startTest();
        update opp;
        Test.stopTest();

        Integer tasksAfter = [SELECT COUNT() FROM Task WHERE WhatId = :opp.Id];
        System.assertEquals(1, tasksAfter,
            'No new task must be created when a won opportunity reverts');
    }

    @IsTest
    static void testUpdateFromNonWonToNonWonChangesNothing() {
        Id accountId = warmAccountId();
        Date closeDate = Date.today().addDays(30);
        Opportunity opp = newOpportunity(accountId, STAGE_PROSPECTING, closeDate);
        insert opp;

        System.assertEquals(0, [SELECT COUNT() FROM Task WHERE WhatId = :opp.Id]);

        opp.StageName = STAGE_QUALIFICATION;
        Test.startTest();
        update opp;
        Test.stopTest();

        System.assertEquals(0, [SELECT COUNT() FROM Task WHERE WhatId = :opp.Id],
            'No task must be created for non-won to non-won updates');
    }

    @IsTest
    static void testAlreadyHotAccountIsNotUpdated() {
        Id accountId = hotAccountId();
        Date closeDate = Date.today().addDays(30);
        Opportunity opp = newOpportunity(accountId, STAGE_CLOSED_WON, closeDate);

        Test.startTest();
        Integer dmlRowsBefore = Limits.getDMLRows();
        insert opp;
        Test.stopTest();
        Integer dmlRowsAfter = Limits.getDMLRows();

        // One row for the Opportunity insert plus one row for the Task.
        // The already-Hot account must not be updated, so no Account row.
        System.assertEquals(2, dmlRowsAfter - dmlRowsBefore,
            'An already-Hot account must not be updated by the handler');

        Account updatedAccount = [SELECT Rating FROM Account WHERE Id = :accountId];
        System.assertEquals('Hot', updatedAccount.Rating);
    }

    @IsTest
    static void testOpportunityWithoutAccountStillCreatesTask() {
        Date closeDate = Date.today().addDays(30);
        Opportunity opp = newOpportunity(null, STAGE_CLOSED_WON, closeDate);

