public with sharing class AccountScoringJob implements Queueable {
    private final List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds;
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    public void execute(QueueableContext context) {
        // execute(null) is supported for direct invocation; context is unused.
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        List<Id> batch = new List<Id>();
        List<Id> remaining = new List<Id>();

        Integer count = 0;
        for (Id accountId : accountIds) {
            if (count < 200) {
                batch.add(accountId);
                count++;
            } else {
                remaining.add(accountId);
            }
        }

        // One SOQL query per execution.
        List<Account> accounts = [
            SELECT Id, AnnualRevenue, Rating
            FROM Account
            WHERE Id IN :batch
        ];

        List<Account> toUpdate = new List<Account>();
        for (Account account : accounts) {
            String rating = calculateRating(account.AnnualRevenue);
            if (account.Rating != rating) {
                account.Rating = rating;
                toUpdate.add(account);
            }
        }

        // One DML statement per execution (at most one).
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }

        // Chain the next batch when Ids remain, including while tests are running.
        if (!remaining.isEmpty()) {
            System.enqueueJob(new AccountScoringJob(remaining));
        }
    }

    private static String calculateRating(Decimal annualRevenue) {
        if (annualRevenue == null) {
            return 'Cold';
        }
        if (annualRevenue >= 1000000) {
            return 'Hot';
        }
        if (annualRevenue >= 100000) {
            return 'Warm';
        }
        return 'Cold';
    }
}
