public with sharing class AccountOnboardingService {

    /**
     * Creates one Account per map entry (named after the entry key) and one Contact
     * per last name in the entry's list (linked to that Account).
     *
     * All inserts are performed through a single fflib_SObjectUnitOfWork and are
     * committed once with commitWork(). No explicit DML is issued by this service.
     *
     * @param contactLastNamesByAccountName Account Name -> list of Contact LastName values
     * @return the inserted Accounts with Ids populated; empty list for null/empty input
     */
    public static List<Account> createAccountsWithContacts(
        Map<String, List<String>> contactLastNamesByAccountName
    ) {
        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return new List<Account>();
        }

        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new Schema.SObjectType[] { Account.SObjectType, Contact.SObjectType }
        );

        List<Account> newAccounts = new List<Account>();

        for (String accountName : contactLastNamesByAccountName.keySet()) {
            if (String.isBlank(accountName)) {
                continue;
            }

            Account account = new Account(Name = accountName);
            uow.registerNewRecord(account, null, (Id) null);
            newAccounts.add(account);

            List<String> lastNames = contactLastNamesByAccountName.get(accountName);
            if (lastNames == null) {
                continue;
            }

            for (String lastName : lastNames) {
                if (String.isBlank(lastName)) {
                    continue;
                }

                Contact contact = new Contact(LastName = lastName);
                uow.registerNewRecord(contact, account, Contact.AccountId);
            }
        }

        if (newAccounts.isEmpty()) {
            return new List<Account>();
        }

        uow.commitWork();
        return newAccounts;
    }
}
