trigger AccountTrigger on Account (after insert) {
    // Callouts cannot be made synchronously from a trigger, and a batch of 200 accounts
    // would exceed the 100-callout-per-transaction limit anyway. The trigger therefore
    // hands the new account IDs to ErpCustomerSync, which processes them asynchronously
    // in chunks of 100 with one HTTP request per account for ERP traceability.
    if (Trigger.isInsert && Trigger.isAfter) {
        Set<Id> accountIdsSet = new Set<Id>();
        for (Account acc : Trigger.new) {
            accountIdsSet.add(acc.Id);
        }
        ErpCustomerSync.enqueue(new List<Id>(accountIdsSet));
    }
}
