// CaseTrigger.trigger
//
// Design notes:
// - After-update only. No SOQL or DML runs in the trigger; the survey work is asynchronous.
// - To stay under the 50 queueable-job limit per transaction, the trigger chunks the case IDs
//   into groups of 50 and enqueues a CaseSurveyJob.Dispatcher per chunk. Each dispatcher then
//   enqueues one CaseSurveyJob per case, so every case is still handled in its own job and one
//   failure cannot affect the others.
//
// Governor note: System.enqueueJob is limited to 50 queueable jobs per transaction. Bulk list-view
// closes and the nightly cleanup (up to 200 cases) would otherwise exceed that limit if every case
// was enqueued directly from the trigger.
trigger CaseTrigger on Case (after update) {
    Set<Id> caseIds = new Set<Id>();
    for (Case closedCase : Trigger.new) {
        Case priorCase = Trigger.oldMap.get(closedCase.Id);

        if (priorCase == null) {
            continue;
        }

        // IsClosed is formula-driven; act only on a real not-closed -> closed transition.
        if (!closedCase.IsClosed || priorCase.IsClosed) {
            continue;
        }

        // Cases without a contact get no survey task.
        if (closedCase.ContactId == null) {
            continue;
        }

        caseIds.add(closedCase.Id);
    }

    if (caseIds.isEmpty()) {
        return;
    }

    List<Id> idList = new List<Id>(caseIds);
    Integer chunkSize = 50;
    for (Integer i = 0; i < idList.size(); i += chunkSize) {
        List<Id> chunk = idList.subList(i, Math.min(i + chunkSize, idList.size()));
        System.enqueueJob(new CaseSurveyJob.Dispatcher(chunk));
    }
}
