// CaseSurveyJob.cls
public with sharing class CaseSurveyJob implements Queueable {
    private final Id caseId;

    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
    }

    public void execute(QueueableContext context) {
        // Re-verify state asynchronously. The case may have been reopened or the contact cleared
        // since the job was enqueued; in those cases no survey task should be created.
        List<Case> cases = [
            SELECT Id,
                   CaseNumber,
                   ContactId,
                   IsClosed
            FROM Case
            WHERE Id = :caseId
            WITH USER_MODE
            LIMIT 1
        ];

        if (cases.isEmpty()) {
            return;
        }

        Case surveyCase = cases.get(0);

        if (!surveyCase.IsClosed || surveyCase.ContactId == null) {
            return;
        }

        Task surveyTask = new Task(
            WhatId = surveyCase.Id,
            WhoId = surveyCase.ContactId,
            Subject = 'CSAT survey: ' + surveyCase.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status = 'Not Started'
        );

        // Let DML failures surface as a failed job for this case only; other cases are unaffected.
        insert surveyTask;
    }

    // Dispatcher that chunks case IDs into groups of 50 so the trigger never exceeds
    // the 50 queueable-job limit in a single transaction while still creating one
    // Queueable job per case.
    public with sharing class Dispatcher implements Queueable {
        private final List<Id> caseIds;
        private static final Integer CHUNK_SIZE = 50;

        public Dispatcher(List<Id> caseIds) {
            this.caseIds = new List<Id>(caseIds);
        }

        public void execute(QueueableContext context) {
            for (Id caseId : caseIds) {
                System.enqueueJob(new CaseSurveyJob(caseId));
            }
        }
    }
}
