import { LightningElement, wire } from 'lwc';
import { MessageContext, subscribe, unsubscribe, publish, APPLICATION_SCOPE } from 'lightning/messageService';
import ACCOUNT_SELECTED from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    @wire(MessageContext) messageContext;

    selectedRecordId = null;
    subscription = null;

    connectedCallback() {
        // Never hold more than one subscription: clear any existing one first.
        if (this.subscription) {
            unsubscribe(this.subscription);
        }
        this.subscription = subscribe(
            this.messageContext,
            ACCOUNT_SELECTED,
            (message) => this.handleMessage(message),
            { scope: APPLICATION_SCOPE }
        );
    }

    disconnectedCallback() {
        if (this.subscription) {
            unsubscribe(this.subscription);
            this.subscription = null;
        }
    }

    handleMessage(message) {
        this.selectedRecordId = message?.recordId || null;
    }

    handleClear() {
        publish(this.messageContext, ACCOUNT_SELECTED, { recordId: null });
    }
}
