public with sharing class GiftImportService {
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    private static final String STATUS_IMPORTED = 'Imported';
    private static final String STATUS_PENDING = 'Pending';
    private static final String DONOR_CONTACT1 = 'Contact1';

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        // Stage one NPSP Data Import record per gift, preserving input order.
        // The staged records remain in the org as the audit trail of the import.
        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            staged.add(new npsp__DataImport__c(
                npsp__Contact1_Firstname__c         = gift.firstName,
                npsp__Contact1_Lastname__c          = gift.lastName,
                npsp__Contact1_Personal_Email__c    = gift.email,
                npsp__Donation_Amount__c            = gift.amount,
                npsp__Donation_Date__c              = gift.giftDate,
                npsp__Donation_Donor__c             = DONOR_CONTACT1,
                npsp__Status__c                     = STATUS_PENDING
            ));
        }

        // One ImportResult per gift, in input order.
        List<ImportResult> results = new List<ImportResult>();
        for (Integer i = 0; i < gifts.size(); i++) {
            results.add(new ImportResult());
        }

        // Insert with all-or-none = false so a row that cannot be staged does not
        // prevent the other rows from being imported.
        List<Database.SaveResult> saveResults = Database.insert(staged, false);
        Set<Id> stagedSuccessIds = new Set<Id>();

        for (Integer i = 0; i < saveResults.size(); i++) {
            if (!saveResults[i].isSuccess()) {
                results[i].success = false;
                if (saveResults[i].getErrors() != null && !saveResults[i].getErrors().isEmpty()) {
                    results[i].errorMessage = saveResults[i].getErrors()[0].getMessage();
                } else {
                    results[i].errorMessage = 'Failed to stage the import record.';
                }
            } else {
                stagedSuccessIds.add(staged[i].Id);
            }
        }

        // Read back the processed records from the database so the results reflect
        // the values NPSP's import processing wrote back (status, matched/created
        // contact, created donation, and any failure information). NPSP applies the
        // org's Data Import settings synchronously as part of the insert transaction.
        if (!stagedSuccessIds.isEmpty()) {
            Map<Id, npsp__DataImport__c> processed = new Map<Id, npsp__DataImport__c>(
                [SELECT npsp__Status__c,
                        npsp__Contact1Imported__c,
                        npsp__DonationImported__c,
                        npsp__FailureInformation__c
                 FROM npsp__DataImport__c
                 WHERE Id IN :stagedSuccessIds]
            );

            for (Integer i = 0; i < saveResults.size(); i++) {
                if (!saveResults[i].isSuccess()) {
                    continue;
                }

                ImportResult r = results[i];
                npsp__DataImport__c di = processed.get(staged[i].Id);

                String status = (di != null && di.npsp__Status__c != null)
                    ? di.npsp__Status__c
                    : String.valueOf(staged[i].npsp__Status__c);
                r.success = STATUS_IMPORTED.equalsIgnoreCase(status);

                r.contactId = (di != null) ? di.npsp__Contact1Imported__c
                                           : staged[i].npsp__Contact1Imported__c;
                r.opportunityId = (di != null) ? di.npsp__DonationImported__c
                                               : staged[i].npsp__DonationImported__c;

                if (!r.success) {
                    r.errorMessage = (di != null && di.npsp__FailureInformation__c != null)
                        ? di.npsp__FailureInformation__c
                        : staged[i].npsp__FailureInformation__c;
                    if (r.errorMessage == null) {
                        r.errorMessage = 'Import did not complete.';
                    }
                }
            }
        }

        return results;
    }
}
