public class RecurringGiftService {
    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    /**
     * Creates one Enhanced Recurring Donation per request and returns the new Ids
     * in request order. NPSP owns installment Opportunity generation; this service
     * only inserts the recurring donation records.
     *
     * Bulk: at most one SOQL query and one DML statement per call.
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        // Validate every request before any DML (and before any SOQL).
        for (GiftRequest req : requests) {
            if (req == null) {
                throw new RecurringGiftException('Recurring gift request cannot be null.');
            }
            if (req.contactId == null) {
                throw new RecurringGiftException('Contact is required for each recurring gift request.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new RecurringGiftException('Amount must be a positive value.');
            }
            if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
                throw new RecurringGiftException('Day of month must be between 1 and 31.');
            }
            if (req.startDate == null) {
                throw new RecurringGiftException('Start date is required for each recurring gift request.');
            }
        }

        // Resolve each donor's account (organization) in a single bulk query.
        Set<Id> contactIds = new Set<Id>();
        for (GiftRequest req : requests) {
            contactIds.add(req.contactId);
        }
        Map<Id, Id> contactToAccountId = new Map<Id, Id>();
        for (Contact donor : [SELECT Id, AccountId FROM Contact WHERE Id IN :contactIds]) {
            contactToAccountId.put(donor.Id, donor.AccountId);
        }

        // Build the recurring donations in request order.
        List<npe03__Recurring_Donation__c> donations = new List<npe03__Recurring_Donation__c>();
        for (GiftRequest req : requests) {
            npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c();
            rd.npe03__Contact__c = req.contactId;

            Id accountId = contactToAccountId.get(req.contactId);
            if (accountId != null) {
                rd.npe03__Organization__c = accountId;
            }

            rd.npe03__Amount__c = req.amount;
            rd.npe03__Installment_Period__c = 'Monthly';
            rd.npe03__Date_Established__c = req.startDate;
            rd.npe03__Next_Payment_Date__c = req.startDate;

            // Open-ended vs fixed-length.
            if (req.installments == null || req.installments == 0) {
                rd.npsp__RecurringType__c = 'Open Ended';
            } else {
                rd.npsp__RecurringType__c = 'Fixed';
                rd.npe03__Installments__c = req.installments;
            }

            // Monthly schedule.
            rd.npsp__InstallmentFrequency__c = 1;
            rd.npsp__Day_of_Month__c = String.valueOf(req.dayOfMonth);
            // Day 31 means "last day of the month" using NPSP's own option;
            // 29 and 30 are stored as those days.
            rd.npsp__Always_Use_Last_Day_Of_Month__c = (req.dayOfMonth == 31);

            rd.npsp__StartDate__c = req.startDate;
            rd.npsp__Status__c = 'Active';
            rd.npsp__PaymentMethod__c = req.paymentMethod;

            donations.add(rd);
        }

        // Single DML; NPSP generates the installment Opportunities itself.
        insert donations;

        // Return Ids in the same order as the input requests.
        List<Id> donationIds = new List<Id>();
        for (npe03__Recurring_Donation__c rd : donations) {
            donationIds.add(rd.Id);
        }
        return donationIds;
    }
