public with sharing class GiftService {
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null) {
            throw new IllegalArgumentException('Contact ID cannot be null.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date cannot be null.');
        }

        List<Contact> contacts = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];

        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist.');
        }

        Contact c = contacts.get(0);

        if (c.AccountId == null) {
            throw new IllegalArgumentException(
                'Contact is not associated with a household account.'
            );
        }

        String dateStr = String.format(
            '{0}-{1}-{2}',
            new List<String>{
                String.valueOf(giftDate.year()),
                String.valueOf(giftDate.month()).leftPad(2, '0'),
                String.valueOf(giftDate.day()).leftPad(2, '0')
            }
        );

        Opportunity opp = new Opportunity(
            Name = String.format(
                '{0} {1} Donation {2}',
                new List<String>{
                    c.FirstName == null ? '' : c.FirstName,
                    c.LastName == null ? '' : c.LastName,
                    dateStr
                }
            ),
            AccountId = c.AccountId,
            npsp__Primary_Contact__c = contactId,
            CloseDate = giftDate,
            StageName = 'Closed Won',
            Amount = amount
        );
        insert opp;

        // Query any roles NPSP or other automation may have already created
        // so we never insert a duplicate contact role.
        List<OpportunityContactRole> existingRoles = [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :opp.Id
        ];

        Map<Id, OpportunityContactRole> roleByContact = new Map<Id, OpportunityContactRole>();
        for (OpportunityContactRole r : existingRoles) {
            roleByContact.put(r.ContactId, r);
        }

        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToUpdate = new List<OpportunityContactRole>();

        // Primary contact must hold the Donor role.
        OpportunityContactRole donorRole = roleByContact.get(contactId);
        if (donorRole == null) {
            rolesToInsert.add(new OpportunityContactRole(
                ContactId = contactId,
                OpportunityId = opp.Id,
                Role = 'Donor',
                IsPrimary = true
            ));
        } else {
            donorRole.Role = 'Donor';
            donorRole.IsPrimary = true;
            rolesToUpdate.add(donorRole);
        }

        // Every other household member holds the Household Member role.
        for (Contact member : [
            SELECT Id
            FROM Contact
            WHERE AccountId = :c.AccountId
              AND Id != :contactId
        ]) {
            OpportunityContactRole memberRole = roleByContact.get(member.Id);
            if (memberRole == null) {
                rolesToInsert.add(new OpportunityContactRole(
                    ContactId = member.Id,
                    OpportunityId = opp.Id,
                    Role = 'Household Member',
                    IsPrimary = false
                ));
            } else {
                memberRole.Role = 'Household Member';
                memberRole.IsPrimary = false;
                rolesToUpdate.add(memberRole);
            }
        }

        if (!rolesToInsert.isEmpty()) {
            insert rolesToInsert;
        }
        if (!rolesToUpdate.isEmpty()) {
            update rolesToUpdate;
        }

        npe01__OppPayment__c payment = new npe01__OppPayment__c(
            npe01__Opportunity__c = opp.Id,
            npe01__Payment_Amount__c = amount,
            npe01__Payment_Date__c = giftDate,
            npe01__Scheduled_Date__c = giftDate,
            npe01__Paid__c = true
        );
        insert payment;

        return opp.Id;
    }
}
