global with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    global override npsp.TDTM_Runnable.DmlWrapper run(List<SObject> newlist,
                                                       List<SObject> oldlist,
                                                       npsp.TDTM_Runnable.Action triggerAction,
                                                       Schema.DescribeSObjectResult objResult) {

        List<Task> tasksToCreate = new List<Task>();
        Map<Id, Opportunity> oldOpportunities = new Map<Id, Opportunity>();

        // Build a lookup of the prior state so we can detect "became Closed Won" transitions.
        if (oldlist != null) {
            for (SObject oldRecord : oldlist) {
                oldOpportunities.put((Id) oldRecord.get('Id'), (Opportunity) oldRecord);
            }
        }

        for (SObject newRecord : newlist) {
            Opportunity opp = (Opportunity) newRecord;

            Boolean isClosedWon = opp.IsClosed && opp.IsWon;
            Boolean isMajorGift = opp.Amount != null && opp.Amount >= 5000;

            if (!isClosedWon || !isMajorGift) {
                continue;
            }

            // If this is an update and the opportunity already qualified before, skip it.
            Opportunity prior = oldOpportunities.get(opp.Id);
            if (prior != null) {
                Boolean wasClosedWon = prior.IsClosed && prior.IsWon;
                Boolean wasMajorGift = prior.Amount != null && prior.Amount >= 5000;
                if (wasClosedWon && wasMajorGift) {
                    continue;
                }
            }

            Task followUp = new Task();
            followUp.Subject = 'Major gift thank-you call';
            followUp.Priority = 'High';
            followUp.Status = 'Not Started';
            followUp.WhatId = opp.Id;
            followUp.WhoId = opp.npsp__Primary_Contact__c; // may be null
            followUp.OwnerId = opp.OwnerId;
            followUp.ActivityDate = (opp.CloseDate != null) ? opp.CloseDate.addDays(3) : null;

            tasksToCreate.add(followUp);
        }

        // Single DML statement; partial success so one bad WhoId does not roll back the batch.
        if (!tasksToCreate.isEmpty()) {
            Database.insert(tasksToCreate, false);
        }

        return new npsp.TDTM_Runnable.DmlWrapper();
    }
}
