public with sharing class RecordAccessService {
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        // Remove any null IDs that might be present in the input set.
        Set<Id> validIds = new Set<Id>();
        for (Id id : recordIds) {
            if (id != null) {
                validIds.add(id);
            }
        }

        if (validIds.isEmpty()) {
            return editable;
        }

        // UserRecordAccess can only be queried for RecordId values that belong
        // to a single object type, so group the input by SObjectType.
        Map<Schema.SObjectType, Set<Id>> idsByObject = new Map<Schema.SObjectType, Set<Id>>();
        for (Id id : validIds) {
            Schema.SObjectType objType = id.getSObjectType();
            Set<Id> typedIds = idsByObject.get(objType);
            if (typedIds == null) {
                typedIds = new Set<Id>();
                idsByObject.put(objType, typedIds);
            }
            typedIds.add(id);
        }

        Id runningUser = UserInfo.getUserId();

        // Use dynamic SOQL because UserRecordAccess does not reliably support
        // bind variables for RecordId in static SOQL (can raise
        // "Variable does not exist" QueryException).
        for (Schema.SObjectType objType : idsByObject.keySet()) {
            Set<Id> typedIds = idsByObject.get(objType);

            List<String> idLiterals = new List<String>();
            for (Id id : typedIds) {
                idLiterals.add('\'' + String.escapeSingleQuotes(String.valueOf(id)) + '\'');
            }

            String query = 'SELECT RecordId, HasEditAccess FROM UserRecordAccess ';
            query += 'WHERE UserId = \'' + String.escapeSingleQuotes(String.valueOf(runningUser)) + '\' ';
            query += 'AND RecordId IN (' + String.join(idLiterals, ',') + ')';

            for (UserRecordAccess ura : Database.query(query)) {
                if (ura.HasEditAccess) {
                    editable.add(ura.RecordId);
                }
            }
        }

        return editable;
    }
}
