public inherited sharing class TA_Account_CreateOnboardingTask
        implements TriggerAction.AfterInsert {

    private static final Set<String> CUSTOMER_TYPES = new Set<String>{
        'Customer - Direct',
        'Customer - Channel'
    };

    /**
     * Trigger Actions Framework entry point (after insert, Account).
     *
     * Creates one onboarding Task per qualifying new Account with a single DML
     * insert for the entire trigger batch. Performs no DML when no Account
     * qualifies.
     */
    public void afterInsert(List<SObject> triggerNew) {
        List<Task> tasks = new List<Task>();
        Date activityDate = Date.today().addDays(7);

        for (SObject record : triggerNew) {
            String type = (String) record.get('Type');
            if (!CUSTOMER_TYPES.contains(type)) {
                continue;
            }

            Id ownerId = (Id) record.get('OwnerId');
            if (ownerId == null) {
                continue;
            }

            tasks.add(new Task(
                Subject = 'Onboard new customer',
                WhatId = (Id) record.get('Id'),
                OwnerId = ownerId,
                ActivityDate = activityDate,
                Status = 'Not Started',
                Priority = 'Normal'
            ));
        }

        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }
}
