public with sharing class OpportunityErpSyncFinalizer implements TriggerAction.DmlFinalizer {
    public void execute(FinalizerHandler.Context context) {
        // The framework invokes every registered finalizer at the end of each DML operation it
        // handles, regardless of sObject. Only enqueue a job when this DML operation collected
        // Opportunity Ids that need syncing, then reset the accumulator so that separate DML
        // statements in the same transaction produce separate jobs (each with only its own Ids).
        Set<Id> opportunityIds = TA_Opportunity_CollectForErpSync.getAndClearCollectedIds();
        if (opportunityIds.isEmpty()) {
            return;
        }

        System.enqueueJob(new OpportunityErpSyncJob(opportunityIds));
    }
}
