public inherited sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accounts = TA_Contact_Queries.getInstance().accountsById;
        if (accounts == null || accounts.isEmpty()) {
            return;
        }

        for (SObject record : triggerNew) {
            Contact c = (Contact) record;
            if (c.AccountId == null) {
                continue;
            }

            Account a = accounts.get(c.AccountId);
            if (a == null) {
                continue;
            }

            // Only inherit when every mailing field is blank; any populated value is kept.
            if (String.isBlank(c.MailingStreet)
                && String.isBlank(c.MailingCity)
                && String.isBlank(c.MailingPostalCode)
                && String.isBlank(c.MailingCountry)) {
                c.MailingStreet = a.BillingStreet;
                c.MailingCity = a.BillingCity;
                c.MailingPostalCode = a.BillingPostalCode;
                c.MailingCountry = a.BillingCountry;
            }
        }
    }
}
